import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../assets/styles/Education.css';

const Education = () => {
  const [educations, setEducations] = useState([]);
  const [formData, setFormData] = useState({
    school: '',
    program: '',
    credential: '',
    date: ''
  });

  const token = localStorage.getItem('token');

  // Load existing entries from backend
  useEffect(() => {
    const fetchEducations = async () => {
      try {
        const res = await axios.get('http://localhost:5000/api/educations', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setEducations(res.data);
      } catch (err) {
        console.error('Error fetching educations:', err.response?.data || err.message);
      }
    };
    if (token) fetchEducations();
  }, [token]);

  // Handle form input
  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  // Add new education
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/educations', formData, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEducations([...educations, res.data]);
      setFormData({ school: '', program: '', credential: '', date: '' });
    } catch (err) {
      console.error('Error adding education:', err.response?.data || err.message);
      alert('Failed to add education entry');
    }
  };

  // Delete education
  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/educations/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEducations(educations.filter((e) => e._id !== id));
    } catch (err) {
      console.error('Error deleting education:', err.response?.data || err.message);
      alert('Failed to delete education entry');
    }
  };

  return (
    <div className="education">
      <h1>Education</h1>

      {/* Static résumé entries */}
      <section className="edu-item">
        <h2>Centennial College, Toronto, ON</h2>
        <p><strong>Program:</strong> Software Engineering Technology – Artificial Intelligence (Co-op)</p>
        <p><strong>Credential:</strong> Advanced Diploma</p>
        <p><strong>Dates:</strong> September 2023 – Present</p>
        <p><strong>Relevant Courses:</strong></p>
        <ul>
          <li>Linux/Unix OS</li>
          <li>Database Concepts (SQL)</li>
          <li>AI Foundations</li>
          <li>Testing & Quality Assurance</li>
          <li>C# Programming</li>
          <li>Web Interface Design</li>
          <li>Web Application Development</li>
          <li>Java Programming</li>
          <li>Ethics of AI</li>
        </ul>
      </section>

      <section className="edu-item">
        <h2>Lambton College, Toronto, ON</h2>
        <p><strong>Program:</strong> Financial Planning & Wealth Management</p>
        <p><strong>Credential:</strong> Certificate</p>
        <p><strong>Date:</strong> April 2020</p>
        <p><strong>Courses:</strong></p>
        <ul>
          <li>Account Concepts and Financial Analysis</li>
          <li>Marketing and Selling</li>
          <li>Banking</li>
        </ul>
      </section>

      <section className="edu-item">
        <h2>Universidad Cooperativa de Colombia, Colombia</h2>
        <p><strong>Program:</strong> Bachelor of Accounting</p>
        <p><strong>Credential:</strong> Bachelor's Degree (WES recognized)</p>
        <p><strong>Date:</strong> December 2010</p>
        <p><strong>Courses:</strong></p>
        <ul>
          <li>Accounting and Finance</li>
          <li>Economics</li>
          <li>Business</li>
        </ul>
      </section>

      {/* Dynamic CRUD section */}
      <h2>Additional Education Entries</h2>
      <form onSubmit={handleSubmit}>
        <input
          name="school"
          value={formData.school}
          onChange={handleChange}
          placeholder="School"
          required
        />
        <input
          name="program"
          value={formData.program}
          onChange={handleChange}
          placeholder="Program"
          required
        />
        <input
          name="credential"
          value={formData.credential}
          onChange={handleChange}
          placeholder="Credential"
          required
        />
        <input
          name="date"
          value={formData.date}
          onChange={handleChange}
          placeholder="Date"
          required
        />
        <button type="submit">Add Education</button>
      </form>

      {educations.map((e) => (
        <section className="edu-item" key={e._id}>
          <h3>{e.school}</h3>
          <p><strong>Program:</strong> {e.program}</p>
          <p><strong>Credential:</strong> {e.credential}</p>
          <p><strong>Date:</strong> {e.date}</p>
          <button onClick={() => handleDelete(e._id)}>Delete</button>
        </section>
      ))}
    </div>
  );
};

export default Education;
